// Some portions generated by Claude
package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * A bare aggregate used as the whole HAVING condition keeps the groups whose aggregate value is true, both for a
 * standard aggregate ({@code SAMPLE}) and for an {@code agg:} extension aggregate ({@code agg:boolAnd}).
 */
public class HavingRootAggregateSparqlTest {

	private static final String PREFIXES = "PREFIX agg: <http://rdf4j.org/aggregate#>\n"
			+ "PREFIX ex: <http://ex/>\n";

	private static SailRepository repository;

	@BeforeAll
	static void setUp() throws Exception {
		repository = new SailRepository(new MemoryStore());
		String data = "@prefix ex: <http://ex/> .\n"
				+ "ex:e1 ex:dept \"eng\" ; ex:active true .\n"
				+ "ex:e2 ex:dept \"eng\" ; ex:active true .\n"
				+ "ex:e3 ex:dept \"ops\" ; ex:active false .\n";
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader(data), "", RDFFormat.TURTLE);
		}
	}

	@AfterAll
	static void tearDown() {
		repository.shutDown();
	}

	private static List<String> depts(String having) {
		String query = PREFIXES + "SELECT ?dept WHERE { ?e ex:dept ?dept ; ex:active ?a } GROUP BY ?dept HAVING ("
				+ having + ")";
		List<String> values = new ArrayList<>();
		try (RepositoryConnection conn = repository.getConnection();
				TupleQueryResult result = conn.prepareTupleQuery(query).evaluate()) {
			for (BindingSet row : QueryResults.asList(result)) {
				assertThat(row.hasBinding("dept")).as("dept bound in " + row).isTrue();
				values.add(row.getValue("dept").stringValue());
			}
		}
		return values;
	}

	@Test
	void bareExtensionAggregateInHavingKeepsTrueGroups() {
		assertThat(depts("agg:boolAnd(?a)")).containsExactly("eng");
	}

	@Test
	void bareStandardAggregateInHavingKeepsTrueGroups() {
		assertThat(depts("SAMPLE(?a)")).containsExactly("eng");
	}

	@Test
	void comparedAggregatesInHavingStillWork() {
		assertThat(depts("agg:boolAnd(?a) = true")).containsExactly("eng");
		assertThat(depts("COUNT(?e) > 1")).containsExactly("eng");
	}
}
